<?php
namespace App\Http\Controllers;
use App\Models\Account;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class AccountController {public function index(){return view('accounts.index',['accounts'=>Account::forCompany(auth()->user()->company_id)->orderBy('code')->get()]);}public function store(Request $r){$c=$r->user()->company_id;$d=$r->validate(['code'=>['required','string','max:30',Rule::unique('accounts')->where(fn($q)=>$q->where('company_id',$c))],'name_en'=>'required|string|max:255','name_ar'=>'nullable|string|max:255','type'=>'required|in:asset,liability,equity,revenue,income,expense','normal_balance'=>'required|in:debit,credit','parent_id'=>'nullable|integer','is_postable'=>'nullable|boolean']);if(!empty($d['parent_id']))Account::forCompany($c)->findOrFail($d['parent_id']);$d['company_id']=$c;$d['is_postable']=$r->boolean('is_postable');Account::create($d);return back()->with('ok','Account created.');}public function update(Request $r,Account $account){if($account->lines()->whereHas('journal',fn($q)=>$q->whereIn('status',['posted','reversed']))->exists()){$allowed=$r->only(['name_en','name_ar','active']);$account->update($allowed);return back()->with('ok','Used account updated without changing accounting classification.');}$d=$r->validate(['name_en'=>'required|string|max:255','name_ar'=>'nullable|string|max:255','type'=>'required|in:asset,liability,equity,revenue,income,expense','normal_balance'=>'required|in:debit,credit','is_postable'=>'nullable|boolean','active'=>'nullable|boolean']);$d['is_postable']=$r->boolean('is_postable');$d['active']=$r->boolean('active');$account->update($d);return back()->with('ok','Account updated.');}}
